    '*' (zero or more of the preceding element), and '+' (one or more of the preceding).
    The algorithm uses recursion to handle different cases based on the pattern and text.
    """

    def is_match(pattern: str, text: str, p_index: int, t_index: int) -> bool:
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.')

        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
